bounded_host_request.command:
set -eu
docker exec -i deploy-postgres-1 sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"' <<'SQL'
BEGIN;
DO $$
DECLARE old_check text; existing_condition text; sale_count integer;
BEGIN
SELECT pg_get_constraintdef(oid) INTO old_check
FROM pg_constraint WHERE conrelid='posting_topics'::regclass AND conname='posting_topics_purpose_check' AND contype='c';
IF old_check IS NULL OR left(old_check,7)<>'CHECK (' THEN RAISE EXCEPTION 'PURPOSE_CONSTRAINT_UNEXPECTED'; END IF;
SELECT count(*) INTO sale_count FROM posting_topics WHERE purpose='video_sale';
IF sale_count<>0 THEN RAISE EXCEPTION 'SALE_PREEXISTS_RECONCILE'; END IF;
IF (SELECT count(*) FROM posting_topics WHERE board_key='video_chat' AND chat_id=-1002373696859
AND message_thread_id=1695 AND purpose='announcement' AND title ILIKE '%稼げる有料動画投稿%'
AND enabled AND verified_by IS NOT NULL AND verified_at IS NOT NULL)<>1
THEN RAISE EXCEPTION 'VERIFIED_SOURCE_TOPIC_NOT_UNIQUE'; END IF;
existing_condition:=substr(old_check,8,length(old_check)-8);
EXECUTE 'ALTER TABLE posting_topics DROP CONSTRAINT posting_topics_purpose_check';
EXECUTE format('ALTER TABLE posting_topics ADD CONSTRAINT posting_topics_purpose_check CHECK ((%s) OR purpose = %L)',existing_condition,'video_sale');
END $$;
INSERT INTO posting_topics(board_key,purpose,chat_id,message_thread_id,title,verified_by,verified_at,enabled)
SELECT board_key,'video_sale',chat_id,message_thread_id,title,verified_by,verified_at,TRUE
FROM posting_topics WHERE board_key='video_chat' AND chat_id=-1002373696859 AND message_thread_id=1695
AND purpose='announcement' AND title ILIKE '%稼げる有料動画投稿%' AND enabled
AND verified_by IS NOT NULL AND verified_at IS NOT NULL;
DO $$
BEGIN
IF (SELECT count(*) FROM posting_topics WHERE purpose='video_sale' AND enabled
AND chat_id=-1002373696859 AND message_thread_id=1695 AND verified_by IS NOT NULL)<>1
THEN RAISE EXCEPTION 'VIDEO_SALE_NOT_INSERTED'; END IF;
END $$;
COMMIT;
SELECT 'VIDEO_SALE_ROUTE_COUNT='||count(*) FROM posting_topics WHERE purpose='video_sale' AND enabled;
SQL
